Value& Rules::stats(const ActorKey&key){auto&i=statistics_[key];if(!rule::isObject(i)){i=object();i.object["actor_kind"]=text(key.first);i.object["actor_id"]=integer(key.second);const auto*a=roundActor(key);i.object["team"]=a?a->get("team"):integer(0);for(auto*k:{"shots_fired","shots_hit","shots_penetrated","max_piercing_series","damage_dealt","damage_received","damage_blocked","damage_assisted_track","damage_assisted_radio","damage_assisted_stun","stun_num","stun_duration_ms","stunned","stun_shots_2","stun_shots_3","kills_assisted_stun","kills_assisted_track","damaged","kills","spotted","capture_points","dropped_capture_points","potential_damage_received","hits_received","piercings_received","no_damage_direct_hits_received","explosion_hits_received","explosion_hits","team_hits","team_damage","team_kills","team_crits","critical_hits","team_damage_penalized","team_killed_durability","life_time","damaging_hits_received","deflected_hits_received","crits_received_mask","hits_with_damage","sniper_damage_dealt","deflected_hits_at_low_health","deflection_streak","best_deflection_streak"})i.object[k]=integer(0);i.object["not_spotted"]=integer(1);i.object["mileage"]=number(0.);i.object["shells_fired"]=object();i.object["equipment_used"]=object();i.object["kill_records"]=array();i.object["damaged_targets"]=array();i.object["damage_sources"]=array();i.object["duelist_sources"]=array();}return i;}
Value Rules::statistics(const ActorKey&key)const{const auto i=statistics_.find(key);return i==statistics_.end()?object():i->second;}
void Rules::increment(const ActorKey&key,const std::string&name,std::int64_t n){rule::add(stats(key),name,n);}
void Rules::interaction(const ActorKey&actor,const ActorKey&target,const std::string&name,std::int64_t amount){auto&own=interactions_[actor];if(!rule::isObject(own))own=object();auto&row=own.object[rule::actorString(target)];if(!rule::isObject(row)){row=object();row.object["target_kind"]=text(target.first);row.object["target_id"]=integer(target.second);row.object["death_reason"]=integer(-1);row.object["mission_events"]=array();row.object["mission_events_complete"]=boolean(true);row.object["mission_events_version"]=integer(5);for(auto*k:{"spotted","direct_hits","explosion_hits","piercings","damage","assist_track","assist_radio","assist_stun","crits","fire","stun_num","stun_duration","damage_blocked","damage_received","ricochets_received","no_damage_direct_hits_received","target_kills","damage_events","kills_assisted_stun","kills_assisted_track","kills_assisted_radio"})row.object[k]=integer(0);}const auto maximum=name=="crits"||name=="damage_blocked"?std::int64_t(UINT32_MAX):name=="spotted"||name=="kills_assisted_stun"||name=="kills_assisted_track"||name=="kills_assisted_radio"?1:name=="target_kills"?255:name=="death_reason"?10:65535;row.object[name]=integer(std::clamp<std::int64_t>(intField(row,name)+amount,name=="death_reason"?-1:0,maximum));}
void Rules::recordDamage(const ActorKey&attacker,const ActorKey&victim,int damage,const Value&before){using namespace rule;if(damage<=0)return;increment(victim,"damage_received",damage);auto*target=state_.actor(victim.first,victim.second);auto*source=roundActor(attacker);if(!source||!target)return;const auto team=intField(*target,"team");auto&row=stats(attacker);if(intField(*source,"team")==team){if(attacker!=victim){increment(attacker,"team_damage",damage);if(!target->get("team_killer").truth()){increment(attacker,"team_damage_penalized",damage);increment(victim,"friendly_damage_received",damage);auto&friendly=row.object["friendly_damage"];friendly.kind=Kind::Object;auto&entry=friendly.object[actorString(victim)];entry.kind=Kind::Object;entry.object["actor_kind"]=text(victim.first);entry.object["actor_id"]=integer(victim.second);entry.object["vehicle"]=target->get("vehicle");add(entry,"damage",damage);}}return;}
 const auto direct_spotters=directSpotters(victim);if(direct_spotters.size()==1&&direct_spotters[0]!=attacker){auto&st=stats(direct_spotters[0]);auto&seen=st.object["exclusive_targets"];seen.kind=Kind::Array;Value target_identity=array();target_identity.array={text(victim.first),integer(victim.second)};if(std::find(seen.array.begin(),seen.array.end(),target_identity)==seen.array.end())seen.array.push_back(target_identity);st.object["exclusive_spot_assists"]=integer(static_cast<std::int64_t>(seen.array.size()));}if(victim.first=="bot"){Value fact=object();fact.object["bot_id"]=integer(victim.second);fact.object["attacker_kind"]=text(attacker.first);fact.object["attacker_id"]=integer(attacker.second);fact.object["damage"]=integer(damage);state_.pending_damage.array.push_back(std::move(fact));}increment(victim,"enemy_damage_received",damage);increment(attacker,"damage_dealt",damage);auto addIdentity=[](Value&v,const ActorKey&key){v.kind=Kind::Array;Value identity=array();identity.array={text(key.first),integer(key.second)};if(std::find(v.array.begin(),v.array.end(),identity)==v.array.end())v.array.push_back(std::move(identity));};addIdentity(row.object["damaged_targets"],victim);row.object["damaged"]=integer(static_cast<std::int64_t>(rows(row.get("damaged_targets")).size()));addIdentity(row.object["support_targets"],victim);addIdentity(stats(victim).object["damage_sources"],attacker);addIdentity(stats(victim).object["duelist_sources"],attacker);interaction(attacker,victim,"damage",damage);interaction(attacker,victim,"damage_events");interaction(victim,attacker,"damage_received",damage);mission(attacker,victim,"damage",{integer(damage),boolean(immobilized(before)),distance(source,target),boolean(invisibleFor(attacker)),state_.server_tick-intField(*source,"room_vision_tick",-100000)<=30?source->get("room_vision_radius"):Value{}});
 std::vector<std::pair<std::string,ActorKey>> impairment;const auto destroyed=strings(before.get("destroyed"));if(destroyed.count("leftTrackHealth")||destroyed.count("rightTrackHealth")){const auto i=track_attackers_.find(victim);if(i!=track_attackers_.end()&&i->second!=attacker)impairment.push_back({"track",i->second});}if(intField(*target,"stun_end_server_time_ms")>state_.server_time_ms){const auto i=stun_attackers_.find(victim);if(i!=stun_attackers_.end()&&i->second!=attacker)impairment.push_back({"stun",i->second});}
 auto credit=[&](const std::string&category,const ActorKey&holder,int amount){const auto*helper=state_.actor(holder.first,holder.second);if(!helper||intField(*helper,"team")==team||amount<=0)return;increment(holder,"damage_assisted_"+category,amount);interaction(holder,victim,"assist_"+category,amount);if(category=="radio")mission(holder,victim,"assist_radio",{integer(amount),boolean(invisibleFor(holder))});Value e=event("assist");e.object["category"]=text(category);e.object["assister_kind"]=text(holder.first);e.object["assister_id"]=integer(holder.second);e.object["attacker_kind"]=text(attacker.first);e.object["attacker_id"]=integer(attacker.second);e.object["target_kind"]=text(victim.first);e.object["target_id"]=integer(victim.second);e.object["damage"]=integer(amount);state_.events.push_back(std::move(e));if(!alive(*target)&&category!="radio"){const auto&previous=interactions_[holder].get(actorString(victim));if(!intField(previous,"kills_assisted_"+category)){increment(holder,"kills_assisted_"+category);interaction(holder,victim,"kills_assisted_"+category);}}};
 for(const auto&holder:impairment)credit(holder.first,holder.second,damage);
 // Only leases actually delivered to this shooter can earn radio assistance.
 // A lease survives its reporter's death; disconnected reporters do not.
 const auto reporters=radioAssisters(attacker,victim);for(std::size_t i=0;i<reporters.size();++i)credit("radio",reporters[i],damage/static_cast<int>(reporters.size())+(i<std::size_t(damage%static_cast<int>(reporters.size()))?1:0));
}
void Rules::recordKill(const ActorKey&attacker,const ActorKey&victim,int reason){using namespace rule;auto*target=state_.actor(victim.first,victim.second);if(!target)return;target->object["death_reason"]=integer(reason);if(!has(stats(victim),"end_tick"))stats(victim).object["end_tick"]=integer(state_.server_tick);if(victim.first=="player")for(const auto&e:rows(target->get("equipment_states")))if(field(e.get("equipment"),"kind")=="rpm_limiter"&&e.get("active").truth()&&intField(e.get("equipment"),"compactDescr")>0)stats(victim).object["equipment_used"].object[std::to_string(intField(e.get("equipment"),"compactDescr"))]=integer(1);target->object["death_attacker_kind"]=text(attacker.first);target->object["death_attacker_id"]=integer(attacker.second);const auto*a=roundActor(attacker);if(!a||attacker==victim)return;for(const auto&helper:radioAssisters(attacker,victim))interaction(helper,victim,"kills_assisted_radio");const bool terminal_immobilized=interactions_[attacker].get(actorString(victim)).get("_terminal_immobilized").truth(immobilized(target->get("critical")));for(const auto&category:std::array<std::string,2>{{"track","stun"}}){const auto&owners=category=="track"?track_attackers_:stun_attackers_;auto holder=owners.find(victim);if(holder==owners.end()||holder->second==attacker||(category=="track"&&!terminal_immobilized)||(category=="stun"&&intField(*target,"stun_end_server_time_ms")<=state_.server_time_ms))continue;const auto*helper=roundActor(holder->second);if(!helper||intField(*helper,"team")==intField(*target,"team"))continue;interaction(holder->second,victim,"kills_assisted_"+category,0);const auto prior=intField(interactions_[holder->second].get(actorString(victim)),"kills_assisted_"+category);if(!prior){interaction(holder->second,victim,"kills_assisted_"+category);increment(holder->second,"kills_assisted_"+category);}}const bool friendly=intField(*a,"team")==intField(*target,"team");if(reason==1&&!friendly&&last_shell_fire_.count(victim)&&last_shell_fire_.at(victim)==attacker){bool enemies=false;for(const auto*actors:{&state_.players,&state_.bots})for(const auto&row:*actors)if(alive(row.second)&&intField(row.second,"team")!=intField(*a,"team"))enemies=true;if(!enemies)stats(attacker).object["last_shell_finisher"]=boolean(true);}auto*source=roundActor(attacker);add(*source,"frags",friendly?-1:1);if(friendly){source->object["team_killer"]=boolean(true);increment(attacker,"team_kills");for(const auto*actors:{&state_.players,&state_.bots})for(const auto&other:*actors){const ActorKey candidate{actors==&state_.bots?"bot":"player",other.first};if(candidate==victim||!alive(other.second)||intField(other.second,"team")==intField(*target,"team"))continue;const auto range=distance(&other.second,target);if(!null(range)&&range.numeric()<=10.99)stats(candidate).object["lucky_devil"]=boolean(true);}if(!target->get("team_killer").truth())increment(attacker,"team_killed_durability",intField(*target,"max_health"));}else{increment(attacker,"kills");interaction(attacker,victim,"target_kills");interactions_[attacker].object[actorString(victim)].object["death_reason"]=integer(reason);mission(attacker,victim,"kill",{integer(reason),boolean(immobilized(target->get("critical"))),distance(source,target),boolean(invisibleFor(attacker)),boolean(alive(*source)&&intField(*source,"health")==intField(*source,"max_health"))});auto&history=interactions_[attacker].object[actorString(victim)].object["mission_events"];if(!history.array.empty())pending_kill_events_.push_back({attacker,victim,history.array.size()-1});Value kill=object();kill.object["actor_kind"]=text(attacker.first);kill.object["actor_id"]=integer(attacker.second);kill.object["victim_kind"]=text(victim.first);kill.object["victim_id"]=integer(victim.second);kill.object["death_reason"]=integer(reason);kill.object["ammo_rack"]=boolean(target->get("critical").get("ammo_rack_death").truth());kill.object["actor_speed"]=number(rounded(std::abs(source->get("speed").numeric()),4));kill.object["victim_speed"]=number(rounded(std::abs(target->get("speed").numeric()),4));kill.object["victim_class"]=target->get("vehicle_class");kill.object["victim_tier"]=target->get("vehicle_tier");kill.object["victim_max_health"]=target->get("max_health");const double dx=source->get("x").numeric()-target->get("x").numeric(),dy=source->get("y").numeric()-target->get("y").numeric(),dz=source->get("z").numeric()-target->get("z").numeric();kill.object["distance"]=number(rounded(std::sqrt(dx*dx+dy*dy+dz*dz),3));kill.object["defended_base"]=boolean(capture_[intField(*source,"team")].contributors.count(actorString(victim))!=0);stats(attacker).object["kill_records"].array.push_back(std::move(kill));}
 Value e=event("vehicle_statistics");e.object["actor_kind"]=text(attacker.first);e.object["actor_id"]=integer(attacker.second);e.object["frags"]=source->get("frags");e.object["team_killer"]=boolean(source->get("team_killer").truth());state_.events.push_back(std::move(e));}
