void Rules::actorAdvanced(const std::string&kind,std::int64_t id,const Value&previous,const Value&publication){using namespace rule;auto*current=state_.actor(kind,id);if(!current)return;const ActorKey key{kind,id};if(kind=="player")recordHumanPose(id,publication);if(!participants_.count(key))participants_[key]=*current;
 if(kind=="bot"){const auto old=intField(previous,"fire_seq"),now=intField(*current,"fire_seq");if(alive(*current)&&(null(previous)||alive(previous))&&now>old&&!publication.get("source_clock_rebase").truth()){Value edges=array();try{edges=botBurstEdges(previous,*current);validateBotInventory(previous,*current,previous.get("room_unavailable_checkpoint").truth());}catch(const std::exception&){edges=array();}for(auto edge:rows(edges)){if(has(publication,"_launch_clock_offset_us"))edge.object["launch_clock_offset_us"]=publication.get("_launch_clock_offset_us");else if(state_.bot_launch_clock_offset_us)edge.object["launch_clock_offset_us"]=integer(*state_.bot_launch_clock_offset_us);if(has(publication,"_presentation_clock_offset_us"))edge.object["presentation_clock_offset_us"]=publication.get("_presentation_clock_offset_us");frozen_edges_[{id,intField(edge,"burst_group_seq")+intField(edge,"burst_index")}]=std::move(edge);}}}
 if(accepting()&&!null(previous)&&alive(previous)&&current->get(kind=="bot"?"world_pose":"client_position").truth()&&previous.get(kind=="bot"?"world_pose":"client_position").truth()){double squared=0.;for(auto*k:{"x","y","z"}){const auto delta=current->get(k).numeric()-previous.get(k).numeric();squared+=delta*delta;}if(std::isfinite(squared))stats(key).object["mileage"]=number(stats(key).get("mileage").numeric()+std::sqrt(squared));}
 if(!alive(*current)&&!has(stats(key),"end_tick"))stats(key).object["end_tick"]=integer(state_.server_tick);
 retryOperations();
}
