void Rules::mission(const ActorKey&actor,const ActorKey&target,const std::string&kind,std::vector<Value>values){using namespace rule;interaction(actor,target,"damage",0);std::size_t total=0;for(const auto&r:interactions_[actor].object)total+=rows(r.second.get("mission_events")).size();auto&row=interactions_[actor].object[actorString(target)];if(total>=1024){row.object["mission_events_complete"]=boolean(false);return;}Value event=array();event.array.push_back(text(kind));event.array.push_back(integer(std::max<std::int64_t>(0,static_cast<std::int64_t>(std::round((double(state_.server_tick)/30.-state_.config.get("prebattle_seconds").numeric(10.))*1000.)))));event.array.insert(event.array.end(),values.begin(),values.end());row.object["mission_events"].array.push_back(std::move(event));}
void Rules::finalizeKillHealth(std::size_t begin){using namespace rule;for(std::size_t i=begin;i<pending_kill_events_.size();++i){const auto&ref=pending_kill_events_[i];const auto&actor=std::get<0>(ref),&target=std::get<1>(ref);const auto index=std::get<2>(ref);auto&events=interactions_[actor].object[actorString(target)].object["mission_events"].array;if(index>=events.size()||events[index].array.size()!=7)continue;const auto*state=state_.actor(actor.first,actor.second);events[index].array[6]=state?boolean(alive(*state)&&intField(*state,"health")==intField(*state,"max_health")):Value{};}}
void Rules::recordCritical(const ActorKey&attacker,const ActorKey&target,const Value&before,const Value&after){using namespace rule;const auto*source=roundActor(attacker),*victim=roundActor(target);if(!source||!victim||attacker==target)return;const bool enemy=intField(*source,"team")!=intField(*victim,"team");if(enemy&&!before.get("fire").truth()&&after.get("fire").truth())mission(attacker,target,"fire",{integer(1)});const auto mask=criticalMask(before,after);if(!mask)return;if(!enemy){increment(attacker,"team_crits",popcount(mask));return;}increment(attacker,"critical_hits",popcount(mask));stats(target).object["crits_received_mask"]=integer(intField(stats(target),"crits_received_mask")|mask);interaction(attacker,target,"crits",0);auto&row=interactions_[attacker].object[actorString(target)];row.object["crits"]=integer(intField(row,"crits")|mask);mission(attacker,target,"critical",{integer(mask)});auto&duel=stats(target).object["duelist_sources"];duel.kind=Kind::Array;Value identity=array();identity.array={text(attacker.first),integer(attacker.second)};if(std::find(duel.array.begin(),duel.array.end(),identity)==duel.array.end())duel.array.push_back(identity);}
void Rules::observeVisibility(const Value&message){using namespace rule;if(!accepting()||!isArray(message.get("contacts")))return;std::map<int,std::map<ActorKey,std::vector<ActorKey>>> direct;std::map<int,std::set<ActorKey>> lit;
 for(int team=1;team<=2;++team)for(auto i=team_visible_[team].begin();i!=team_visible_[team].end();)if(team_lit_deadlines_[team][*i]<=state_.monotonic_seconds)i=team_visible_[team].erase(i);else ++i;for(auto&team:team_lit_deadlines_)team.second.clear();for(auto*actors:{&state_.players,&state_.bots})for(auto&row:*actors){row.second.object["radio_assist_sources"]=object();row.second.object["room_direct_targets"]=array();row.second.object["room_visible_to_enemy"]=boolean(false);row.second.object.erase("room_vision_radius");row.second.object.erase("room_vision_tick");}
 for(const auto&contact:rows(message.get("contacts"))){const int team=static_cast<int>(intField(contact,"observing_team"));const auto raw_kind=field(contact,"target_kind");const ActorKey target{raw_kind=="human"?"player":"bot",intField(contact,"target_id")};auto*victim=state_.actor(target.first,target.second);if((team!=1&&team!=2)||!victim||!alive(*victim)||intField(*victim,"team")==team)continue;if(contact.get("visible").truth()&&contact.get("time_left").numeric()>0.){lit[team].insert(target);team_lit_deadlines_[team][target]=state_.monotonic_seconds+contact.get("time_left").numeric();victim->object["room_visible_to_enemy"]=boolean(true);}for(const auto&observer_kind:std::array<std::pair<const char*,const char*>,2>{{{"player","visible_by_player_ids"},{"bot","visible_by_bot_ids"}}})for(const auto&raw:rows(contact.get(observer_kind.second))){const ActorKey observer{observer_kind.first,exactInteger(raw).value_or(0)};auto*actor=state_.actor(observer.first,observer.second);if(!actor||!alive(*actor)||intField(*actor,"team")!=team)continue;direct[team][target].push_back(observer);actor->object["room_direct_targets"].array.push_back(text(actorString(target)));}
  for(const auto&recipient:rows(contact.get("radio_recipients"))){ActorKey receiver{field(recipient,"kind")=="human"?"player":"bot",intField(recipient,"id")};auto*actor=state_.actor(receiver.first,receiver.second);if(!actor||intField(*actor,"team")!=team)continue;auto&provenance=actor->object["radio_assist_sources"];provenance.kind=Kind::Object;Value sources=array();for(const auto&source:rows(recipient.get("sources"))){ActorKey reporter{field(source,"kind")=="human"?"player":"bot",intField(source,"id")};const auto*helper=state_.actor(reporter.first,reporter.second);if(!helper||intField(*helper,"team")!=team||source.get("time_left").numeric()<=0.)continue;Value lease=object();lease.object["kind"]=text(reporter.first);lease.object["id"]=integer(reporter.second);lease.object["deadline"]=number(state_.monotonic_seconds+source.get("time_left").numeric());sources.array.push_back(std::move(lease));}provenance.object[actorString(target)]=std::move(sources);}}
 for(const auto&team:direct)for(const auto&target:team.second)ever_spotted_.insert(target.first);
 for(int team=1;team<=2;++team){for(const auto&target:direct[team])if(!team_visible_[team].count(target.first)){stats(target.first).object["not_spotted"]=integer(0);for(const auto&reporter:target.second){interaction(reporter,target.first,"spotted",0);auto&row=interactions_[reporter].object[actorString(target.first)];if(intField(row,"spotted"))continue;row.object["spotted"]=integer(1);increment(reporter,"spotted");const auto*victim=state_.actor(target.first.first,target.first.second);if(victim&&field(*victim,"vehicle_class")=="SPG")increment(reporter,"spotted_spgs");mission(reporter,target.first,"spot",{boolean(!ever_spotted_.count(reporter))});if(reporter.first=="player"){Value e=event("detection");e.object["observer_kind"]=text("player");e.object["observer_id"]=integer(reporter.second);e.object["target_kind"]=text(target.first.first);e.object["target_id"]=integer(target.first.second);state_.events.push_back(std::move(e));}}}team_visible_[team]=lit[team];for(const auto&target:direct[team])team_visible_[team].insert(target.first);}
 for(const auto&r:rows(message.get("player_vision_ranges"))){auto*actor=state_.actor("player",intField(r,"id"));if(actor){actor->object["room_vision_radius"]=r.get("radius");actor->object["room_vision_tick"]=integer(state_.server_tick);}}
}
